import{ChannelType as m,SlashCommandBuilder as d}from"discord.js";var r=class s{static enabled=!1;static commandName="discord_delete_all_messages";static description="Delete all messages in a specified channel.";static subName="channel";static subDescription="Channel to delete messages from";createSlashCommand(){return new d().setName(s.commandName).setDescription(s.description).addChannelOption(o=>o.setName(s.subName).setDescription(s.subDescription).addChannelTypes(m.GuildText).setRequired(!0))}createCommandFunctionality(){return async function(t){try{await t.reply("\u{1F5D1}\uFE0F Deleting all messages...");let e=t.options.getChannel(s.subName);if(!e||e.type!==m.GuildText)return await t.editReply("\u274C Invalid channel provided.");let n=0,l;do{l=await e.messages.fetch({limit:100});let a=l.filter(i=>Date.now()-i.createdTimestamp<14*24*60*60*1e3);a.size>0&&(await e.bulkDelete(a,!0),n+=a.size)}while(l.size===100);let c=(await e.messages.fetch({limit:100})).filter(a=>Date.now()-a.createdTimestamp>=14*24*60*60*1e3).map(async a=>{try{await a.delete(),n++}catch(i){console.warn(`Skipping message deletion due to error: ${i.message}`)}});await Promise.allSettled(c),await t.followUp(`\u2705 Successfully deleted ${n} messages.`)}catch(e){console.error(`Error deleting messages: ${e.message}`),await t.followUp("\u274C Failed to delete messages.")}}}async createObject(){return{data:this.createSlashCommand(),execute:this.createCommandFunctionality()}}};export{r as default};
